            "title": "Heart Disease Dataset Logistic Classification",
            "dataset": "https://archive.ics.uci.edu/ml/datasets/heart+disease",
            "tasks": [
              "Analyze clinical patterns and relationships among features and heart disease outcomes.",
              "Build a classification model using Logistic Regression and Multinomial Logistic Regression.",
              "Evaluate performance using Accuracy, Precision, Recall, F1-score, and ROC-AUC metrics."
            ]
